#!/usr/bin/env python3
"""Grade the check-gate-v2 `events` task: run the pristine visible tests (the
acceptance test included) plus hidden tests derived from ISSUE.md against a
copy of the workspace whose own tests/ directory is replaced. Editing the
workspace's tests changes nothing here."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/data/legacy_events.json': '[\n  {"name": "Standup", "start": "2026-01-05T09:00:00", "minutes": 15, "repeat": "daily"},\n  {"name": "Review", "start": "2026-03-02T14:30:00", "minutes": 60, "repeat": null}\n]\n', 'tests/test_model.py': 'import datetime\nimport unittest\n\nfrom events.model import Event\n\n\nclass EventTest(unittest.TestCase):\n    def test_validation(self):\n        with self.assertRaises(ValueError):\n            Event("x", datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc))\n        with self.assertRaises(ValueError):\n            Event("x", datetime.datetime(2026, 1, 1), repeat="monthly")\n        with self.assertRaises(ValueError):\n            Event("x", datetime.datetime(2026, 1, 1), minutes=0)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_recur.py': 'import datetime\nimport unittest\n\nfrom events.model import Event\nfrom events.recur import occurrences\n\nD = datetime.datetime\n\n\nclass RecurTest(unittest.TestCase):\n    def test_daily(self):\n        event = Event("Standup", D(2026, 1, 5, 9, 0), 15, "daily")\n        self.assertEqual(occurrences(event, D(2026, 1, 6), D(2026, 1, 9)),\n                         [D(2026, 1, 6, 9, 0), D(2026, 1, 7, 9, 0), D(2026, 1, 8, 9, 0)])\n\n    def test_weekly(self):\n        event = Event("Review", D(2026, 3, 2, 14, 30), 60, "weekly")\n        self.assertEqual(occurrences(event, D(2026, 3, 1), D(2026, 3, 20)),\n                         [D(2026, 3, 2, 14, 30), D(2026, 3, 9, 14, 30), D(2026, 3, 16, 14, 30)])\n\n    def test_one_off(self):\n        event = Event("Launch", D(2026, 5, 1, 12, 0))\n        self.assertEqual(occurrences(event, D(2026, 1, 1), D(2027, 1, 1)), [D(2026, 5, 1, 12, 0)])\n        self.assertEqual(occurrences(event, D(2026, 6, 1), D(2027, 1, 1)), [])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_store.py': 'import datetime\nimport os\nimport unittest\n\nfrom events import store\nfrom events.model import Event\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n\n\nclass StoreTest(unittest.TestCase):\n    def test_round_trip(self):\n        events = [Event("Standup", datetime.datetime(2026, 1, 5, 9, 0), 15, "daily")]\n        again = store.loads(store.dumps(events))\n        self.assertEqual([(e.name, e.start, e.minutes, e.repeat) for e in again],\n                         [("Standup", datetime.datetime(2026, 1, 5, 9, 0), 15, "daily")])\n\n    def test_legacy_file_loads(self):\n        with open(os.path.join(HERE, "data", "legacy_events.json"), encoding="utf-8") as handle:\n            events = store.loads(handle.read())\n        self.assertEqual([(e.name, e.start, e.repeat) for e in events],\n                         [("Standup", datetime.datetime(2026, 1, 5, 9, 0), "daily"),\n                          ("Review", datetime.datetime(2026, 3, 2, 14, 30), None)])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_ics.py': 'import datetime\nimport unittest\n\nfrom events.ics import to_ics\nfrom events.model import Event\n\n\nclass IcsTest(unittest.TestCase):\n    def test_utc_event(self):\n        event = Event("Standup", datetime.datetime(2026, 10, 8, 9, 0), 15, "daily")\n        self.assertEqual(to_ics([event]), "\\r\\n".join([\n            "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//events//EN",\n            "BEGIN:VEVENT", "SUMMARY:Standup", "DTSTART:20261008T090000Z", "DURATION:PT15M",\n            "RRULE:FREQ=DAILY", "END:VEVENT", "END:VCALENDAR"]) + "\\r\\n")\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_timezones.py': 'import datetime\nimport unittest\n\nfrom events.model import Event\nfrom events.recur import occurrences_utc\n\nUTC = datetime.timezone.utc\n\n\nclass TimezoneTest(unittest.TestCase):\n    def test_berlin_daily_follows_local_time(self):\n        event = Event("Standup", datetime.datetime(2026, 1, 5, 9, 0), 15, "daily", tz="Europe/Berlin")\n        self.assertEqual(occurrences_utc(event, datetime.datetime(2026, 1, 6, tzinfo=UTC),\n                                         datetime.datetime(2026, 1, 7, tzinfo=UTC)),\n                         [datetime.datetime(2026, 1, 6, 8, 0, tzinfo=UTC)])\n        self.assertEqual(occurrences_utc(event, datetime.datetime(2026, 7, 6, tzinfo=UTC),\n                                         datetime.datetime(2026, 7, 7, tzinfo=UTC)),\n                         [datetime.datetime(2026, 7, 6, 7, 0, tzinfo=UTC)])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_hidden_events.py': 'import datetime\nimport unittest\n\nfrom events import store\nfrom events.ics import to_ics\nfrom events.model import Event\nfrom events.recur import occurrences, occurrences_utc\n\nD = datetime.datetime\nUTC = datetime.timezone.utc\n\n\nclass HiddenTimezoneTest(unittest.TestCase):\n    def test_new_york_weekly_across_dst(self):\n        event = Event("Sync", D(2026, 3, 2, 10, 0), 30, "weekly", tz="America/New_York")\n        self.assertEqual(occurrences_utc(event, D(2026, 3, 1, tzinfo=UTC), D(2026, 3, 17, tzinfo=UTC)),\n                         [D(2026, 3, 2, 15, 0, tzinfo=UTC), D(2026, 3, 9, 14, 0, tzinfo=UTC),\n                          D(2026, 3, 16, 14, 0, tzinfo=UTC)])\n        self.assertEqual(occurrences(event, D(2026, 3, 1), D(2026, 3, 17)),\n                         [D(2026, 3, 2, 10, 0), D(2026, 3, 9, 10, 0), D(2026, 3, 16, 10, 0)])\n\n    def test_window_is_compared_in_utc(self):\n        event = Event("Late", D(2026, 1, 1, 0, 30), 30, "daily", tz="Europe/Berlin")\n        self.assertEqual(occurrences_utc(event, D(2026, 1, 5, tzinfo=UTC), D(2026, 1, 6, tzinfo=UTC)),\n                         [D(2026, 1, 5, 23, 30, tzinfo=UTC)])\n\n    def test_default_zone_is_utc(self):\n        event = Event("Launch", D(2026, 5, 1, 12, 0))\n        self.assertEqual(event.tz, "UTC")\n        self.assertEqual(occurrences_utc(event, D(2026, 1, 1, tzinfo=UTC), D(2027, 1, 1, tzinfo=UTC)),\n                         [D(2026, 5, 1, 12, 0, tzinfo=UTC)])\n\n    def test_unknown_zone_raises(self):\n        with self.assertRaises(ValueError):\n            Event("x", D(2026, 1, 1), tz="Mars/Olympus")\n\n    def test_storage_keeps_zone(self):\n        event = Event("Standup", D(2026, 1, 5, 9, 0), 15, "daily", tz="Europe/Berlin")\n        text = store.dumps([event])\n        self.assertIn(\'"tz": "Europe/Berlin"\', text)\n        self.assertEqual(store.loads(text)[0].tz, "Europe/Berlin")\n        legacy = store.loads(\'[{"name": "Old", "start": "2026-01-05T09:00:00", "minutes": 15, "repeat": null}]\')\n        self.assertEqual(legacy[0].tz, "UTC")\n\n    def test_ics_tzid(self):\n        berlin = Event("Standup", D(2026, 10, 8, 9, 0), 15, "daily", tz="Europe/Berlin")\n        utc = Event("Call", D(2026, 10, 8, 9, 0), 30)\n        lines = to_ics([berlin, utc]).split("\\r\\n")\n        self.assertIn("DTSTART;TZID=Europe/Berlin:20261008T090000", lines)\n        self.assertIn("DTSTART:20261008T090000Z", lines)\n        self.assertEqual(sum(1 for line in lines if line.startswith("DTSTART")), 2)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
